  const handler = buildApp(store, { roles: {}, principals: {} }, POLICY,
    { webhook_secrets: [SECRET], tolerance_s: 300 });
  const server = createServer((req, res) => void handler(req, res));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve())));
  const address = server.address();
  assert.ok(address && typeof address !== "string");
  const url = `http://127.0.0.1:${address.port}`;
  const post = async (raw: string, headers: Record<string, string> = {
    "Paygate-Signature": header(raw, Math.floor(Date.now() / 1000)),
  }) => {
    const res = await fetch(`${url}/webhooks/paygate`, { method: "POST", body: raw, headers });
    return { status: res.status, body: await res.json() };
  };
  return { dir, store, post, url };
}

test("rotation accepts any signature paired with any configured secret", () => {
  const raw = JSON.stringify(event("evt_rotation"));
  const sigs = `t=${NOW},v1=${"0".repeat(64)},v1=${computeSignature(SECRET, NOW, raw)}`;
  assert.doesNotThrow(() => verifyWebhook(raw, sigs, ["old-secret", SECRET], NOW));
  assert.doesNotThrow(() => verifyWebhook(raw, header(raw), [SECRET, "next-secret"], NOW));
  assert.throws(() => verifyWebhook(raw, sigs, [], NOW), SignatureError);
});

test("timestamp tolerance is inclusive and enforced in both directions", () => {
  const raw = "{}";
  for (const offset of [-300, 300]) {
    assert.doesNotThrow(() => verifyWebhook(raw, header(raw), [SECRET], NOW + offset));
  }
  for (const offset of [-301, 301]) {
    assert.throws(() => verifyWebhook(raw, header(raw), [SECRET], NOW + offset), SignatureError);
  }
});

test("signatures cover exact raw bytes, not reserialized JSON", () => {
  const raw = '{\n  "message": "₹5,000", "value": 1\n}\n';
  const sig = createHmac("sha256", SECRET).update(`${NOW}.`).update(Buffer.from(raw)).digest("hex");
  assert.doesNotThrow(() => verifyWebhook(Buffer.from(raw), `t=${NOW},v1=${sig}`, [SECRET], NOW));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(raw)), `t=${NOW},v1=${sig}`, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(raw + " ", header(raw), [SECRET], NOW), SignatureError);
});

test("missing and malformed signature headers fail closed", () => {
  for (const value of [undefined, "", `v1=${"a".repeat(64)}`, `t=${NOW}`, `t=NaN,v1=${"a".repeat(64)}`,
    `t=${NOW},v1=abc`, `t=${NOW},v1=${"A".repeat(64)}`, `t=${NOW},t=${NOW},v1=${"a".repeat(64)}`,
    `t=999999999999999999999,v1=${"a".repeat(64)}`]) {
    assert.throws(() => verifyWebhook("{}", value, [SECRET], NOW), SignatureError);
  }
  assert.throws(() => parseSignatureHeader("malformed"), SignatureError);
});

test("processed IDs survive restart and duplicates do not mutate or audit", (t) => {
  const { store, dir } = fixture(t);
  const ev = parseEvent(JSON.stringify(event("evt_persist")));
  processEvent(store, POLICY, ev);
  const before = snapshot(dir);
  const restarted = new Store(dir);
  assert.deepEqual(processEvent(restarted, POLICY, { ...ev, type: "refund.cancelled" }), { outcome: "duplicate" });
  assert.deepEqual(snapshot(dir), before);
  assert.equal(restarted.listRefunds().length, 1);
});

test("cancelled, ignored, and unknown events are deduplicated too", (t) => {
  const { store, dir } = fixture(t);
  processEvent(store, POLICY, parseEvent(JSON.stringify(event("evt_request", "refund.requested", 500001))));
  const cancel = parseEvent(JSON.stringify(event("evt_cancel", "refund.cancelled")));
  processEvent(store, POLICY, cancel);
  assert.equal(store.listRefunds()[0].status, "cancelled");
  const ignored = parseEvent(JSON.stringify(event("evt_ignored_cancel", "refund.cancelled")));
  processEvent(store, POLICY, ignored);
  const unknown = parseEvent(JSON.stringify({ event_id: "evt_unknown", type: "payment.updated", created: NOW }));
  processEvent(store, POLICY, unknown);
  const before = snapshot(dir);
  for (const ev of [cancel, ignored, unknown]) {
    assert.equal(processEvent(store, POLICY, ev).outcome, "duplicate");
  }
  assert.deepEqual(snapshot(dir), before);
});

test("auto-approved cancellation is audited once and does not change status", (t) => {
  const { store, dir } = fixture(t);
  processEvent(store, POLICY, parseEvent(JSON.stringify(event("evt_auto"))));
  const ev = parseEvent(JSON.stringify(event("evt_auto_cancel", "refund.cancelled")));
  assert.equal(processEvent(store, POLICY, ev).outcome, "ignored");
  const before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, ev).outcome, "duplicate");
  assert.equal(store.listRefunds()[0].status, "auto_approved");
  assert.deepEqual(snapshot(dir), before);
  assert.equal(readFileSync(join(dir, "audit.jsonl"), "utf8").split("cancel.ignored").length - 1, 1);
});

test("event IDs that coincide with prototype properties are real IDs", (t) => {
  const { store, dir } = fixture(t);
  for (const id of ["constructor", "__proto__", "toString"]) {
    const ev = parseEvent(JSON.stringify(event(id)));
    assert.equal(processEvent(store, POLICY, ev).outcome, "processed");
    assert.equal(processEvent(new Store(dir), POLICY, ev).outcome, "duplicate");
  }
});

test("finance threshold is inclusive, INR-only, and replay guards are retained", () => {
  const cfg = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(cfg.auto_approve_max_minor, 500000);
  assert.deepEqual(cfg.auto_approve_currencies, ["INR"]);
