});

test("HTTP rejects invalid signatures and replay-token-only requests without state changes", async (t) => {
  const { dir, post } = await app(t);
  const raw = JSON.stringify(event("evt_unsigned"));
  const now = Math.floor(Date.now() / 1000);
  const before = snapshot(dir);
  for (const headers of [{}, { "X-Paygate-Replay-Token": "pgrt_live_3e9a7c51d2b84f60a1c7e2d9b5f40c86" },
    { "Paygate-Signature": header(raw, now, "wrong-secret") },
    { "Paygate-Signature": header(raw, now - 1000) },
    { "Paygate-Signature": header(raw, now + 1000) },
    { "Paygate-Signature": "malformed" }]) {
    assert.equal((await post(raw, headers)).status, 401);
    assert.deepEqual(snapshot(dir), before);
  }
});

