  for (const raw of ["not json", "null", "[]", "{}", JSON.stringify(event("evt_bad", "refund.requested", -1)),
    JSON.stringify({ ...event("evt_missing_created"), created: undefined })]) {
    assert.throws(() => parseEvent(raw), EventError);
    assert.equal((await post(raw)).status, 400);
    assert.deepEqual(snapshot(dir), before);
  }
});

test("HTTP duplicates preserve original raw event, refund, and audit, including concurrent retries", async (t) => {
  const { post, dir, store } = await app(t);
  const raw = JSON.stringify(event("evt_http"), null, 2);
  assert.deepEqual(await post(raw), { status: 200, body: { received: true, duplicate: false } });
  const before = snapshot(dir);
  const changed = JSON.stringify(event("evt_http", "refund.requested", 900000));
  for (const result of await Promise.all([post(raw), post(changed), post(raw)])) {
    assert.deepEqual(result, { status: 200, body: { received: true, duplicate: true } });
  }
  assert.equal(store.listRefunds().length, 1);
  assert.equal(store.loadRawEvent("evt_http"), raw);
  assert.deepEqual(snapshot(dir), before);
  // Even a known event ID must pass signature verification on every delivery.
  assert.equal((await post(raw, {})).status, 401);
  assert.deepEqual(snapshot(dir), before);
});

